import os
import sys


class Predict(object):
    """Hopsworks predictor wrapping the trigram scorer model."""

    def __init__(self):
        for var in ("MODEL_FILES_PATH", "ARTIFACT_FILES_PATH"):
            path = os.environ.get(var)
            if path and os.path.isdir(path) and path not in sys.path:
                sys.path.insert(0, path)
        try:
            from scorer import score
        except ImportError:
            import math

            A = 0.517051
            B = 1.682507
            C = 2.459943
            D = 1.826126

            def score(text):
                ll = 0.0
                for i in range(len(text) - 2):
                    o0, o1, o2 = (ord(ch) for ch in text[i:i + 3])
                    ll += math.sin(A * o0 + B * o1 + C * o2 + D)
                return {"score": round(ll, 6)}

        self._score = score

    def predict(self, inputs):
        return [self._score(text)["score"] for text in inputs]

